find_rule:
js:
var d = [];
var html = request(input);
var items = pdfa(html, ".manga-list .manga-item");
for (var i = 0; i < items.length; i++) {
  var item = items[i];
  var title = pdfh(item, ".manga-title&&Text");
  var cover = pd(item, "img&&src||img&&data-src", input);
  var url = pd(item, "a&&href", input);
  var update = pdfh(item, ".latest-chapter&&Text");
  if (title && url) {
    d.push({
      title: title.trim(),
      desc: update.trim(),
      pic_url: cover ? cover + '@Referer=' + input : '',
      url: url,
      col_type: 'movie_3'
    });
  }
}
setResult(d);

