detail_find_rule:
js:
var d = [];
var html = request(input);
var comicTitle = pdfh(html, ".manga-detail h1&&Text") || '漫画详情';
var cover = pd(html, ".manga-cover img&&src", input);
var desc = pdfh(html, ".manga-summary&&Text");

// 1. 顶部大剧名卡片
d.push({
  title: '剧名：' + comicTitle,
  desc: desc,
  pic_url: cover ? cover + '@Referer=' + input : '',
  url: input,
  col_type: 'pic_1_card'
});

// 2. 章节目录列表 (以话数为选集)
d.push({
  title: '【章节目录】',
  col_type: 'text_1'
});
var chapters = pdfa(html, ".chapter-list li a");
for (var i = 0; i < chapters.length; i++) {
  var ch = chapters[i];
  var chTitle = pdfh(ch, "Text") || ('第' + (i + 1) + '话');
  var chUrl = pd(ch, "a&&href", input);
  d.push({
    title: chTitle.trim(),
    url: chUrl,
    col_type: 'text_3'
  });
}
setResult(d);

lazy:
js:
// 漫画图片抓取逻辑：进入章节页获取所有漫画长图列表
var html = request(input);
var d = [];
var imgUrls = [];
// 匹配内联动态章节图片数组，例如 var chapterImages = [...] 或 DOM 图片列表
var match = html.match(/chapterImages\s*=\s*(\[[\s\S]*?\]);/);
if (match && match[1]) {
  try {
    imgUrls = JSON.parse(match[1]);
  } catch (e) {}
}
if (imgUrls.length === 0) {
  var imgNodes = pdfa(html, ".comic-page img, .reader-images img");
  for (var i = 0; i < imgNodes.length; i++) {
    var src = pd(imgNodes[i], "img&&data-src||img&&src", input);
    if (src) imgUrls.push(src);
  }
}
// 双端图片阅读器渲染：按大图卡片推入
for (var k = 0; k < imgUrls.length; k++) {
  var img = imgUrls[k];
  if (img.indexOf('http') !== 0) img = 'https:' + img;
  d.push({
    pic_url: img + '@Referer=' + input,
    col_type: 'pic_1_full'
  });
}
setResult(d);
